Here is the commit message:
tpm: st33zp24: Fix missing cleanup on get_burstcount() error

get_burstcount() can return -EBUSY on timeout. When this happens,
st33zp24_send() returns directly without releasing the locality
acquired earlier.

Use goto out_err to ensure proper cleanup when get_burstcount() fails.

Fixes: bf38b8710892 ("tpm/tpm_i2c_stm_st33: Split tpm_i2c_tpm_st33 in 2 layers (core + phy)")
Signed-off-by: Alper Ak <alperyasinak1@gmail.com>
Signed-off-by: Jarkko Sakkinen <jarkko@kernel.org>

Here is the root cause:
The bug is due to a missing cleanup (release of locality) when `get_burstcount()` fails. In `st33zp24_send()`, after acquiring the locality, the code enters a loop that calls `get_burstcount()`. If `get_burstcount()` returns a negative error (e.g., `-EBUSY` on timeout), the original code immediately returns that error without jumping to the cleanup label `out_err`, which releases the locality. This causes a resource leak and leaves the TPM in an inconsistent state. The fix ensures that on `get_burstcount()` failure, the error is stored and control flows to the existing cleanup path.

Here is the patch:
  */
 static int st33zp24_send(struct tpm_chip *chip, unsigned char *buf,
 			 size_t bufsiz, size_t len)
 {
 	struct st33zp24_dev *tpm_dev = dev_get_drvdata(&chip->dev);
 	u32 status, i, size, ordinal;
 	int burstcnt = 0;
 	int ret;
 	u8 data;

 	if (len < TPM_HEADER_SIZE)
 		return -EBUSY;

 	ret = request_locality(chip);
 	if (ret < 0)
 		return ret;

 	status = st33zp24_status(chip);
 	if ((status & TPM_STS_COMMAND_READY) == 0) {
 		st33zp24_cancel(chip);
 		if (wait_for_stat
 		    (chip, TPM_STS_COMMAND_READY, chip->timeout_b,
 		     &tpm_dev->read_queue, false) < 0) {
 			ret = -ETIME;
 			goto out_err;
 		}
 	}

 	for (i = 0; i < len - 1;) {
 		burstcnt = get_burstcount(chip);
-		if (burstcnt < 0)
-			return burstcnt;
+		if (burstcnt < 0) {
+			ret = burstcnt;
+			goto out_err;
+		}
 		size = min_t(int, len - i - 1, burstcnt);
 		ret = tpm_dev->ops->send(tpm_dev->phy_id, TPM_DATA_FIFO,
 					 buf + i, size);
 		if (ret < 0)
 			goto out_err;

 		i += size;
 	}

 	status = st33zp24_status(chip);
 	if ((status & TPM_STS_DATA_EXPECT) == 0) {
 		ret = -EIO;
 		goto out_err;
 	}

 	ret = tpm_dev->ops->send(tpm_dev->phy_id, TPM_DATA_FIFO,
 				 buf + len - 1, 1);
 	if (ret < 0)
 		goto out_err;

 	status = st33zp24_status(chip);
 	if ((status & TPM_STS_DATA_EXPECT) != 0) {
 		ret = -EIO;
 		goto out_err;
 	}

 	data = TPM_STS_GO;
 	ret = tpm_dev->ops->send(tpm_dev->phy_id, TPM_STS, &data, 1);
 	if (ret < 0)
 		goto out_err;

 	if (chip->flags & TPM_CHIP_FLAG_IRQ) {
 		ordinal = be32_to_cpu(*((__be32 *) (buf + 6)));

 		ret = wait_for_stat(chip, TPM_STS_DATA_AVAIL | TPM_STS_VALID,
 				tpm_calc_ordinal_duration(chip, ordinal),
 				&tpm_dev->read_queue, false);
 		if (ret < 0)
 			goto out_err;
 	}

 	return 0;
 out_err:
 	st33zp24_cancel(chip);
 	release_locality(chip);
 	return ret;
 }



